import crypto from "node:crypto";

export function receive(req, secret) {
  const raw = req.rawBody;
  const received = req.headers["x-hub-signature-256"];
  const expected = "sha256=" + crypto
    .createHmac("sha256", secret)
    .update(raw)
    .digest("hex");

  if (!received || !crypto.timingSafeEqual(
    Buffer.from(received), Buffer.from(expected)
  )) return {status: 401};

  return {status: 200, event: JSON.parse(raw)};
}

