const allowed = new Set((process.env.GITHUB_IPS ?? "").split(",").filter(Boolean));

export function handleWebhook(req, res) {
  const sourceIp = req.socket.remoteAddress?.replace(/^::ffff:/, "");
  if (!sourceIp || !allowed.has(sourceIp)) {
    res.writeHead(403);
    return res.end("forbidden");
  }
  // Also verify the webhook signature and payload.
  res.writeHead(204);
  res.end();
}

const seen = new Set<string>();

export function handleWebhook(req: Request): Response {
  const deliveryId = req.headers.get("X-GitHub-Delivery");
  if (!deliveryId) return new Response("Missing delivery ID", { status: 400 });
  if (seen.has(deliveryId)) return new Response("Already processed", { status: 200 });
  seen.add(deliveryId);
  // Perform the one-time action here.
  return new Response("Accepted", { status: 200 });
}

import crypto from "node:crypto";

export function verifyWebhook(rawBody: string, received: string, secret: string) {
  const expected = "sha256=" + crypto
    .createHmac("sha256", secret)
    .update(rawBody)
    .digest("hex");
  const a = Buffer.from(received);
  const b = Buffer.from(expected);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}
